/** Runs all report builders in sequence. Continues on error; reports results. Safe to re-run. */
function buildAllReports() {
  const reports = [
    { name: "ThemeSummary", fn: buildThemeSummary },
    { name: "SatisfactionByRole", fn: buildSatisfactionByRole }
  ];
  const succeeded = [];
  const failed = [];
  reports.forEach(r => {
    try { r.fn(); succeeded.push(r.name); }
    catch (err) { failed.push(r.name + ": " + err.message); }
  });
  let msg;
  if (!failed.length) {
    msg = "All built: " + succeeded.join(", ");
  } else {
    msg = "OK: " + (succeeded.join(", ") || "none") +
          " | Failed: " + failed.join("; ");
  }
  SpreadsheetApp.getActiveSpreadsheet().toast(msg, "Reports", 5);
}
