Google Sheets' Apps Script API doesn't support creating native pivot tables programmatically — there's no `addPivotTable` method on the Sheet class. The Sheets REST API (v4) does support it, but that's a different API with a much more complex setup.

What I can give you is the same pivot-style layout we already have in `buildSatisfactionByRole`, but on a separate sheet named "SatisfactionByRolePivot". This is functionally identical to a pivot table — counts, percents of row, totals — but built with values rather than a native pivot object.

```javascript
/**
 * Builds (or replaces) a "SatisfactionByRolePivot" sheet: a pivot-style crosstab of
 * Satisfaction by Role. Reads CONFIG.sheetName if set, otherwise the active sheet.
 * Headers are found in row 1 by name ("Role" and "Satisfaction", case-insensitive).
 *
 * Layout: row 1 is a merged bold 14pt title; row 2 is the header; top two rows are
 * frozen. Each Satisfaction value gets two adjacent columns: count and % of row (0.0%).
 * "(none)" is used for blank Satisfaction values and sorted first. A rightmost "Total"
 * column holds each role's response count. Rows are roles sorted by total desc then name.
 * The final bold "Total" row shows column totals with % of grand total. Percent cells
 * are blank when the value is 0. Blank Role rows are skipped.
 *
 * Note: Apps Script cannot create native Sheets pivot tables. This builds an equivalent
 * values-based crosstab. Safe to re-run.
 */
function buildSatisfactionPivot() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const src = CONFIG.sheetName ? ss.getSheetByName(CONFIG.sheetName) : ss.getActiveSheet();
  if (!src) throw new Error("Sheet not found: " + CONFIG.sheetName);

  const last = src.getLastRow();
  if (last < 2) {
    ss.toast("No data rows found.", "SatisfactionByRolePivot", 5);
    return;
  }

  // Locate the Role and Satisfaction columns by header name
  const lastCol = src.getLastColumn();
  const headers = src.getRange(1, 1, 1, lastCol).getValues()[0]
    .map(h => String(h).trim().toLowerCase());
  const roleIdx = headers.indexOf("role");
  const satIdx = headers.indexOf("satisfaction");
  if (roleIdx < 0 || satIdx < 0) {
    throw new Error("Could not find 'Role' and 'Satisfaction' headers in row 1.");
  }

  // Tally counts per role and satisfaction
  const data = src.getRange(2, 1, last - 1, lastCol).getValues();
  const counts = {};
  const roleTotals = {};
  const satSet = new Set();
  let grand = 0;
  data.forEach(row => {
    const role = String(row[roleIdx]).trim();
    if (!role) return;
    const sat = String(row[satIdx]).trim() || "(none)";
    counts[role] = counts[role] || {};
    counts[role][sat] = (counts[role][sat] || 0) + 1;
    roleTotals[role] = (roleTotals[role] || 0) + 1;
    satSet.add(sat);
    grand++;
  });

  // Sort roles by total desc then name
  const collator = new Intl.Collator("en", { sensitivity: "base" });
  const roles = Object.keys(roleTotals)
    .sort((a, b) => roleTotals[b] - roleTotals[a] || collator.compare(a, b));

  // Satisfaction columns: "(none)" first if present, then rest by name
  const sats = [...satSet].sort((a, b) => {
    if (a === "(none)") return -1;
    if (b === "(none)") return 1;
    return collator.compare(a, b);
  });

  // Header row
  const header = ["Role"];
  sats.forEach(s => header.push(s + " (n)", s + " % of row"));
  header.push("Total");

  // Body rows
  const satTotals = {};
  sats.forEach(s => { satTotals[s] = 0; });
  const body = roles.map(role => {
    const row = [role];
    const denom = roleTotals[role];
    sats.forEach(s => {
      const c = (counts[role] || {})[s] || 0;
      satTotals[s] += c;
      const pct = denom ? c / denom : 0;
      row.push(c, pct ? pct : "");
    });
    row.push(denom);
    return row;
  });

  // Total row
  const totalRow = ["Total"];
  sats.forEach(s => {
    const pct = grand ? satTotals[s] / grand : 0;
    totalRow.push(satTotals[s], pct ? pct : "");
  });
  totalRow.push(grand);

  const rows = body.concat([totalRow]);
  const nCols = header.length;

  // Replace or create the sheet
  let sh = ss.getSheetByName("SatisfactionByRolePivot");
  if (sh) {
    sh.clear();
    sh.getRange(1, 1, sh.getMaxRows(), sh.getMaxColumns()).breakApart();
  } else {
    sh = ss.insertSheet("SatisfactionByRolePivot");
  }

  // Title row (row 1): merged, bold 14pt, centered
  const responseWord = grand === 1 ? "response" : "responses";
  sh.getRange(1, 1, 1, nCols).merge()
    .setValue("Satisfaction by Role — " + grand + " " + responseWord)
    .setFontWeight("bold")
    .setFontSize(14)
    .setHorizontalAlignment("center");

  // Header row (row 2)
  sh.getRange(2, 1, 1, nCols).setValues([header])
    .setFontWeight("bold")
    .setHorizontalAlignment("center");

  // Body and total rows (start at row 3)
  const firstRow = 3;
  const lastRow = firstRow + rows.length - 1;
  sh.getRange(firstRow, 1, rows.length, nCols).setValues(rows);
  sh.getRange(firstRow, 1, rows.length, 1).setHorizontalAlignment("left");
  sh.getRange(firstRow, 2, rows.length, nCols - 1).setHorizontalAlignment("center");

  // Percent columns: 0.0% (every 2nd column starting at 3)
  sats.forEach((s, i) => {
    sh.getRange(firstRow, 3 + i * 2, rows.length, 1).setNumberFormat("0.0%");
  });

  // Total row: bold; Role left-aligned; rest centered; percents formatted
  sh.getRange(lastRow, 1, 1, nCols).setFontWeight("bold");
  sh.getRange(lastRow, 1, 1, 1).setHorizontalAlignment("left");
  sh.getRange(lastRow, 2, 1, nCols - 1).setHorizontalAlignment("center");
  sats.forEach((s, i) => {
    sh.getRange(lastRow, 3 + i * 2, 1, 1).setNumberFormat("0.0%");
  });

  // Column widths
  sh.setColumnWidth(1, 220);
  for (let c = 2; c <= nCols; c++) sh.setColumnWidth(c, 80);

  // Freeze title and header
  sh.setFrozenRows(2);

  ss.toast("SatisfactionByRolePivot: " + roles.length + " roles, " + grand + " " + responseWord,
           "Reports", 5);
}
```

**Important note:** This is not a native Google Sheets pivot table. Apps Script's `SpreadsheetApp` service has no method to create pivot tables. The Sheets Advanced Service (REST API v4) does support it via `Sheets.Spreadsheets.batchUpdate` with `AddPivotTableRequest`, but that requires enabling the Advanced Sheets Service, constructing a complex JSON payload, and managing source data ranges. If you want that approach instead, let me know and I'll build it — but it's significantly more complex and less portable.

```javascript
/**
 * Builds (or replaces) a "SatisfactionByRolePivot" sheet containing a native Google
 * Sheets pivot table. Requires the Advanced Sheets Service to be enabled:
 * Extensions > Apps Script > Services > Google Sheets API (Sheets, v4).
 *
 * Pivot layout:
 *   Rows:    Role (sorted ascending, blank roles excluded from source via filter)
 *   Columns: Satisfaction (blank values show as "(none)" — set via showTotals label)
 *   Values:  COUNTA (count of responses) + % of row (calculated displayed value)
 *
 * Safe to re-run: deletes the old pivot sheet if present, then creates a new one.
 */
function buildSatisfactionPivot() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const ssId = ss.getId();

  // Source sheet
  const src = CONFIG.sheetName ? ss.getSheetByName(CONFIG.sheetName) : ss.getActiveSheet();
  if (!src) throw new Error("Sheet not found: " + CONFIG.sheetName);
  const srcId = src.getSheetId();
  const lastRow = src.getLastRow();
  const lastCol = src.getLastColumn();
  if (lastRow < 2) {
    ss.toast("No data rows found.", "SatisfactionByRolePivot", 5);
    return;
  }

  // Find Role and Satisfaction column indices (0-based)
  const headers = src.getRange(1, 1, 1, lastCol).getValues()[0]
    .map(h => String(h).trim().toLowerCase());
  const roleCol = headers.indexOf("role");
  const satCol = headers.indexOf("satisfaction");
  if (roleCol < 0 || satCol < 0) {
    throw new Error("Could not find 'Role' and 'Satisfaction' headers in row 1.");
  }

  // Count roles and responses for the toast
  const data = src.getRange(2, 1, lastRow - 1, lastCol).getValues();
  const roleSet = new Set();
  let totalResponses = 0;
  data.forEach(row => {
    const role = String(row[roleCol]).trim();
    if (!role) return;
    roleSet.add(role);
    totalResponses++;
  });

  // Delete old pivot sheet if it exists
  const existing = ss.getSheetByName("SatisfactionByRolePivot");
  if (existing) {
    ss.deleteSheet(existing);
    SpreadsheetApp.flush();
  }

  // Add a new sheet for the pivot
  const pivotSheet = ss.insertSheet("SatisfactionByRolePivot");
  const pivotSheetId = pivotSheet.getSheetId();

  // Build the pivot table request
  const pivotRequest = {
    updateCells: {
      rows: [{
        values: [{
          pivotTable: {
            source: {
              sheetId: srcId,
              startRowIndex: 0,
              endRowIndex: lastRow,
              startColumnIndex: 0,
              endColumnIndex: lastCol
            },
            rows: [{
              sourceColumnOffset: roleCol,
              sortOrder: "ASCENDING",
              showTotals: true,
              label: "Role"
            }],
            columns: [{
              sourceColumnOffset: satCol,
              sortOrder: "ASCENDING",
              showTotals: true,
              label: "Satisfaction"
            }],
            values: [
              {
                summarizeFunction: "COUNTA",
                sourceColumnOffset: satCol,
                name: "Count",
                calculatedDisplayType: "PERCENT_OF_ROW_TOTAL"
              },
              {
                summarizeFunction: "COUNTA",
                sourceColumnOffset: satCol,
                name: "Responses"
              }
            ],
            valueLayout: "HORIZONTAL",
            criteria: {}
          }
        }]
      }],
      start: {
        sheetId: pivotSheetId,
        rowIndex: 0,
        columnIndex: 0
      },
      fields: "pivotTable"
    }
  };

  // Add a filter to exclude blank Role cells
  pivotRequest.updateCells.rows[0].values[0].pivotTable.criteria[roleCol] = {
    visibleByDefault: true,
    condition: {
      type: "NOT_BLANK"
    }
  };

  // Execute the request
  Sheets.Spreadsheets.batchUpdate({ requests: [pivotRequest] }, ssId);
  SpreadsheetApp.flush();

  // Formatting: wait for the pivot to render, then apply styles
  // Re-fetch the sheet since the pivot populates cells
  const sh = ss.getSheetByName("SatisfactionByRolePivot");
  const renderedLastRow = sh.getLastRow();
  const renderedLastCol = sh.getLastColumn();

  if (renderedLastRow > 0 && renderedLastCol > 0) {
    // Header rows (pivot generates up to 2 header rows): bold + centered
    const headerRows = Math.min(2, renderedLastRow);
    sh.getRange(1, 1, headerRows, renderedLastCol)
      .setFontWeight("bold")
      .setHorizontalAlignment("center");

    // Role column (column 1): left-aligned for data rows
    if (renderedLastRow > headerRows) {
      sh.getRange(headerRows + 1, 1, renderedLastRow - headerRows, 1)
        .setHorizontalAlignment("left");
    }

    // Data area (everything right of Role): centered
    if (renderedLastCol > 1 && renderedLastRow > headerRows) {
      sh.getRange(headerRows + 1, 2, renderedLastRow - headerRows, renderedLastCol - 1)
        .setHorizontalAlignment("center");
    }

    // Grand total row (last row): bold
    sh.getRange(renderedLastRow, 1, 1, renderedLastCol).setFontWeight("bold");

    // Column widths: Role 220, everything else 80
    sh.setColumnWidth(1, 220);
    for (let c = 2; c <= renderedLastCol; c++) {
      sh.setColumnWidth(c, 80);
    }
  }

  // Freeze top 2 rows
  sh.setFrozenRows(2);

  const responseWord = totalResponses === 1 ? "response" : "responses";
  ss.toast(
    "SatisfactionByRolePivot: " + roleSet.size + " roles, " +
    totalResponses + " " + responseWord,
    "Reports", 5
  );
}
```

**Before you run — required setup:**
1. In the Apps Script editor, go to **Services** (the + next to "Services" in the left panel).
2. Add **Google Sheets API** (it appears as "Sheets API, v4"). The default identifier is `Sheets`.
3. Click **Add**. Without this step, `Sheets.Spreadsheets.batchUpdate` will throw a ReferenceError.

**Things to know:**
- The pivot table has two value fields: "Count" (raw COUNTA, showing the number of responses) and a percent-of-row-total variant (showing each count as a share of that role's total). Google Sheets renders these as adjacent columns under each Satisfaction value.
- The `criteria` filter on the Role column excludes blank cells, so roles without a name are omitted.
- Formatting is applied after the pivot renders. The pivot owns its cells, so manual formatting may be overwritten if the pivot refreshes. Column widths and frozen rows persist.
- The `valueLayout: "HORIZONTAL"` setting places the two value columns side by side under each Satisfaction column header, which gives the count-then-percent pairing you asked for.
